"""Referentiels de competences par metier (valeurs par defaut, INDICATIVES et modifiables).

Ecrits une seule fois dans data/config/skills_referentials.json ; l'utilisateur les modifie ensuite depuis
l'interface (ajout/suppression de mots-cles, coefficients 1-3) sans toucher au code.
Format d'une competence : (nom, coefficient, [synonymes]).  Coefficient : 3 = essentielle, 2 = importante, 1 = un plus.
"""

S = lambda n, w=2, a=(): {"name": n, "weight": w, "aliases": list(a)}  # noqa: E731


def _role(label, kw, skills):
    return {"label": label, "title_keywords": kw, "skills": skills}


